require_once __DIR__.'/includes/letters.php';LetterModule::requireCapability('settings');$pageTitle='تنظیمات نامه‌های سازمانی';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/letter-settings.php');}try{$values=['auto_numbering'=>isset($_POST['auto_numbering'])?'1':'0','number_prefix'=>mb_substr(trim((string)($_POST['number_prefix']??'')),0,30),'number_next'=>(string)max(1,(int)($_POST['number_next']??1)),'default_font'=>mb_substr(trim((string)($_POST['default_font']??'')),0,100),'default_font_size'=>(string)max(10,min(24,(int)($_POST['default_font_size']??14))),'default_paper_size'=>in_array($_POST['default_paper_size']??'',['A4','A5'],true)?$_POST['default_paper_size']:'A4','default_orientation'=>($_POST['default_orientation']??'')==='landscape'?'landscape':'portrait'];foreach(['margin_top','margin_right','margin_bottom','margin_left'] as $key)$values[$key]=(string)max(5,min(40,(int)($_POST[$key]??18)));foreach($values as $key=>$value)Database::execute('INSERT INTO site_settings(setting_key,setting_value,setting_type,updated_at) VALUES(?,?,"text",NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()',['letter_'.$key,$value]);$signUsers=array_map('intval',$_POST['sign_users']??[]);$issueUsers=array_map('intval',$_POST['issue_users']??[]);foreach(Database::fetchAll('SELECT id FROM users WHERE status="active" AND role NOT IN ("admin","super_admin")') as $permissionUser){$uid=(int)$permissionUser['id'];foreach(['letters.sign'=>in_array($uid,$signUsers,true),'letters.issue'=>in_array($uid,$issueUsers,true)] as $module=>$allowed)Database::execute('INSERT INTO user_permissions(user_id,module_key,can_view,can_create,can_edit,can_delete,created_at) VALUES(?,?,?,0,?,0,NOW()) ON DUPLICATE KEY UPDATE can_view=VALUES(can_view),can_edit=VALUES(can_edit)',[$uid,$module,$allowed?1:0,$allowed?1:0]);}Auth::log((int)Auth::user()['id'],'letter_settings_updated','letter_settings');flash('تنظیمات و دسترسی‌های نامه ذخیره شد.');}catch(Throwable $e){error_log('Letter settings: '.$e->getMessage());flash('ذخیره تنظیمات انجام نشد.','danger');}redirect('/admin/letter-settings.php');}
$permissionUsers=Database::fetchAll('SELECT u.id,u.name,u.role,u.department,MAX(CASE WHEN p.module_key="letters.sign" THEN p.can_edit ELSE 0 END) can_sign,MAX(CASE WHEN p.module_key="letters.issue" THEN p.can_edit ELSE 0 END) can_issue FROM users u LEFT JOIN user_permissions p ON p.user_id=u.id AND p.module_key IN ("letters.sign","letters.issue") WHERE u.status="active" AND u.role NOT IN ("admin","super_admin") GROUP BY u.id,u.name,u.role,u.department ORDER BY u.name');
