<?php $roleLabels=['manager'=>'مدیر','employee'=>'کارمند'];?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><section class="card letter-form-section"><h2>شماره‌گذاری</h2><div class="grid grid-3"><label class="checkbox-item"><input type="checkbox" name="auto_numbering" <?=letter_setting('auto_numbering','1')==='1'?'checked':''?>> شماره‌گذاری خودکار هنگام صدور</label><label class="form-field"><span>پیشوند شماره</span><input name="number_prefix" value="<?=e(letter_setting('number_prefix','SH-'))?>" maxlength="30"></label><label class="form-field"><span>شماره بعدی</span><input type="number" min="1" name="number_next" value="<?=e(letter_setting('number_next','1'))?>"></label></div></section><section class="card letter-form-section"><h2>ظاهر و چاپ</h2><div class="grid grid-3"><label class="form-field"><span>فونت پیش‌فرض</span><input name="default_font" value="<?=e(letter_setting('default_font','Vazirmatn, Tahoma, sans-serif'))?>"></label><label class="form-field"><span>سایز فونت</span><input type="number" min="10" max="24" name="default_font_size" value="<?=e(letter_setting('default_font_size','14'))?>"></label><label class="form-field"><span>کاغذ پیش‌فرض</span><select name="default_paper_size"><option value="A4" <?=letter_setting('default_paper_size','A4')==='A4'?'selected':''?>>A4</option><option value="A5" <?=letter_setting('default_paper_size')==='A5'?'selected':''?>>A5</option></select></label><label class="form-field"><span>جهت پیش‌فرض</span><select name="default_orientation"><option value="portrait" <?=letter_setting('default_orientation','portrait')==='portrait'?'selected':''?>>عمودی</option><option value="landscape" <?=letter_setting('default_orientation')==='landscape'?'selected':''?>>افقی</option></select></label><?php foreach(['margin_top'=>'بالا','margin_right'=>'راست','margin_bottom'=>'پایین','margin_left'=>'چپ'] as $key=>$label):?><label class="form-field"><span>حاشیه <?=$label?> (میلی‌متر)</span><input type="number" min="5" max="40" name="<?=$key?>" value="<?=e(letter_setting($key,'18'))?>"></label><?php endforeach?></div></section><section class="card letter-form-section"><h2>دسترسی صدور و امضا</h2><p class="muted">مدیران سامانه همیشه دسترسی کامل دارند. دبیرخانه نیز به‌صورت خودکار امکان صدور و بایگانی دارد.</p><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>نقش / واحد</th><th>اجازه امضا</th><th>اجازه صدور</th></tr></thead><tbody><?php foreach($permissionUsers as $pu):?><tr><td><?=e($pu['name'])?></td><td><?=e(($roleLabels[$pu['role']]??'کاربر').' / '.($pu['department']?:'—'))?></td><td><input type="checkbox" name="sign_users[]" value="<?=$pu['id']?>" <?=(int)$pu['can_sign']?'checked':''?>></td><td><input type="checkbox" name="issue_users[]" value="<?=$pu['id']?>" <?=(int)$pu['can_issue']?'checked':''?>></td></tr><?php endforeach?></tbody></table></div></section><section class="card"><p class="muted">دسترسی مشاهده، ایجاد پیش‌نویس، ویرایش، بایگانی و مشاهده محرمانه همچنان از ماتریس مجوزهای کاربران پنل قابل مدیریت است.</p><button class="btn btn-primary">ذخیره تنظیمات و دسترسی‌ها</button></section></form><?php require __DIR__.'/../views/partials/admin-footer.php';?>
